import numpy as np
from scipy.optimize import minimize

def f_sphere(params):
    phi, theta = params
    x = np.sqrt(3) * np.sin(phi) * np.cos(theta)
    y = np.sqrt(3) * np.sin(phi) * np.sin(theta)
    z = np.sqrt(3) * np.cos(phi)
    return -(x*y**3 + y*z**3 + z*x**3)

extrema = []
for p in np.linspace(0, np.pi, 50):
    for t in np.linspace(0, 2*np.pi, 100):
        res = minimize(f_sphere, [p, t], bounds=[(0, np.pi), (0, 2*np.pi)])
        if res.success:
            val = -res.fun
            extrema.append((val, res.x))

# Find unique extrema
unique_extrema = []
for val, params in extrema:
    is_new = True
    for u_val, u_params in unique_extrema:
        if abs(val - u_val) < 1e-4:
            # Check if params are similar
            if np.allclose(params, u_params, atol=1e-3) or \
               np.allclose(params, (u_params[1], u_params[0]), atol=1e-3): # wrap around
                is_new = False
                break
    if is_new:
        unique_extrema.append((val, params))

print(f"Unique extrema values: {[e[0] for e in unique_extrema]}")

import numpy as np
from scipy.optimize import fsolve

def system_all(vars):
    x, y, z, lam = vars
    return [
        x**2 + y**2 + z**2 - 3,
        y**3 + 3*z*x**2 - 2*lam*x,
        3*x*y**2 + z**3 - 2*lam*y,
        3*y*z**2 + x**3 - 2*lam*z
    ]

solutions = []
# Use a grid of starting points
search_range = np.linspace(-2, 2, 6)
for x0 in search_range:
    for y0 in search_range:
        for z0 in search_range:
            # Estimate lam
            if x0 != 0:
                lam0 = (y0**3 + 3*z0*x0**2) / (2*x0)
            else:
                lam0 = 0
            sol, info, ier, msg = fsolve(system_all, [x0, y0, z0, lam0], full_output=True)
            if ier == 1:
