import numpy as np
from scipy.optimize import minimize

def objective(coords):
    u, v, w = coords
    return -(u*v**3 + v*w**3 + w*u**3)

def constraint(coords):
    u, v, w = coords
    return u**2 + v**2 + w**2 - 1

cons = {'type': 'eq', 'fun': constraint}
# Use many random starts to find the global maximum
max_val = -np.inf
best_coords = None

for _ in range(100):
    start = np.random.uniform(-1, 1, 3)
    # Normalize start to be on the sphere
    start = start / np.linalg.norm(start)
    res = minimize(objective, start, constraints=cons)
    if res.success:
        if -res.fun > max_val:
            max_val = -res.fun
            best_coords = res.x
print(f"Maximum found: {max_val}")

